mapper.update:
update SIMULATION_ITEM
set SIMULATION_ITEM_NAME = #{simulationItemName},
    SIMULATION_ITEM_APPLY_AMOUNT = #{simulationItemApplyAmount},
    APPLY_START_DATE = #{applyStartDate},
    APPLY_END_DATE = #{applyEndDate},
    RECURRENCE_TYPE = #{recurrenceType}
where SIMULATION_ITEM_ID = #{simulationItemId}
  and SIMULATION_ID = #{simulationId}
  and IS_DELETED = false

update SIMULATION_ITEM
set IS_DELETED = true
where SIMULATION_ITEM_ID = #{itemId}
    and SIMULATION_ID = #{simulationId}
    and IS_DELETED = false
